#include<bits/stdc++.h>using namespace std ;using ll = long long ;const int mod = 1e9 + 7 ;  struct Node{         ll g , cnt; };  ll gcd (ll a , ll b){         if(b == 0){                  return a;          }          return gcd(b , a % b); }  class segTree{         int n ;          vector<Node>seg;         public:          segTree(int n){                  this -> n = n ;                  seg.resize(4 * n);          }          Node Merge(Node &left , Node &right){                  Node res ;                    res.g = gcd(left.g , right.g);                    res.cnt = 0 ;                   if(res.g == left.g){                           res.cnt += left.cnt ;                  }                   if(res.g == right.g){                           res.cnt += right.cnt;                  }                   return res ;         }          void Build(int idx , int l , int r , vector<ll>&arr){                  if(l == r){                           seg[idx].g = arr[l];                            seg[idx].cnt = 1;                             return ;                   }                   int mid = (l + r) >> 1;                   Build(2 * idx + 1 , l , mid , arr);                   Build(2 * idx + 2 , mid + 1 , r , arr);                    seg[idx] = Merge(seg[2 * idx + 1] , seg[2 * idx + 2]);          }          Node Query(int idx , int l , int r , int left , int right){                  if (r < left || l > right)                  {                           return {0, 0}; // neutral for gcd                  }                  if (l >= left && r <= right)                  {                           return seg[idx];                  }                   int mid = (l + r) >> 1;                    Node L = Query(2 * idx + 1 , l , mid , left , right);                   Node R = Query(2 * idx + 2 , mid + 1 , r , left , right) ;                   return Merge(L , R);          } };    int32_t main(){         ios :: sync_with_stdio(false);          cin.tie(nullptr);           ll n ;          cin >> n ;           vector<ll>arr(n);         for(ll i = 0 ; i < n ; i ++){                  cin >> arr[i] ;          }          segTree *seg = new segTree(n);          seg -> Build(0 , 0 , n - 1 , arr);          ll q;          cin >> q;           while(q --){                  int l , r ;                   cin >> l >> r ;                   l -- , r -- ;                  Node res = seg -> Query(0 , 0 , n - 1 , l , r);                                  ll total = r - l + 1 ;                  cout << total - res.cnt << endl ;         }          return  0;}